import org.springframework.web.server.ServerWebExchange;
import org.springframework.web.server.WebFilter;
import org.springframework.web.server.WebFilterChain;
import reactor.core.publisher.Mono;

public class TenantContextWebFilter implements WebFilter {
    public static final String TENANT_KEY = "currentTenant";

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, WebFilterChain chain) {
        String tenantId = exchange.getRequest().getHeaders().getFirst("X-Tenant-ID");
        if (tenantId == null || tenantId.isBlank()) {
            return Mono.error(new IllegalArgumentException("Missing Tenant Header"));
        }
        return chain.filter(exchange)
                .contextWrite(context -> context.put(TENANT_KEY, tenantId));
    }
}
